-- Monthly partitions for interaction history
-- build {{sim.sessionId}}
CREATE TABLE interactions_p (LIKE interactions INCLUDING ALL) PARTITION BY RANGE (started_at);
CREATE TABLE interactions_2026_10 PARTITION OF interactions_p FOR VALUES FROM ('2026-10-01') TO ('2026-11-01');

// Resumable backfill for partitioned interaction history
// build {{sim.sessionId}}
export const BATCH = 5_000;

export async function backfill(cursor: string | null, copy: (from: string | null, n: number) => Promise<string | null>): Promise<void> {
  let next = cursor;
  do next = await copy(next, BATCH);
  while (next);
}

// Dual-write to the legacy and partitioned tables
// build {{sim.sessionId}}
export async function dualWrite<T>(legacy: (r: T) => Promise<void>, partitioned: (r: T) => Promise<void>, row: T): Promise<void> {
  await legacy(row);
  await partitioned(row);
}

// Interaction history store (reads from the partitioned table)
// build {{sim.sessionId}}
export const HISTORY_TABLE = 'interactions_p';
